import React, { HTMLAttributes, useEffect, useRef, useState } from "react";
import { Alert, Container, OverlayTrigger, Popover } from "react-bootstrap";
import { Route, useLocation, useNavigate } from "react-router-dom";

import "./Book.css";

import { Library } from "../library/Library";

import { ColorMode, titleToSnake } from "../../../utils";

import InteractiveBookNavigation from "../../interface/navigationBar";
import { useColorMode } from "../../interface/ColorModeToggle";
import { PrivateLibrary } from "../library/privateLibrary";
import { Quiz } from "../activity/quiz/Quiz";
import { Audio } from "../../media/audio/Audio";

interface BookData extends Required<Omit<BookOptions, "pages">> {
    id: number;
    key: string;
    pages: BookPageData[];
    readable: boolean;
    activities: BookActivitiesData;
}

interface BookOptions {
    title: string;
    description?: string;
    cover?: React.DetailedReactHTMLElement<HTMLAttributes<HTMLDivElement>, HTMLDivElement>;
    pages?: BookPageOptions[];
    activities?: BookActivities;
}

interface BookActivitiesData extends Required<BookActivities> {}

interface BookActivities {
    quiz?: Quiz;
}

interface BookPageData extends Required<Omit<BookPageOptions, "conversation">> {
    conversation: BookPageDialogueData[];
    content: () => React.ReactNode;
}

interface BookPageOptions {
    conversation?: BookPageDialogueOptions[];
    content?: React.ReactNode | (() => React.ReactNode);
}

interface BookPageDialogueData extends Required<Omit<BookPageDialogueOptions, "audio">> {
    audio: Audio;
}

interface BookPageDialogueOptions {
    audio?: string;
    content?: React.ReactNode;
    timeout?: number;
}

type BookPageDialogueControlType = "previous" | "mute" | "unmute" | "play" | "pause" | "reset" | "repeat" | "next";
interface BookPageDialogueControlOptions {
    page: number;
    dialogue: number;
    type: BookPageDialogueControlType;
}

type BookPageMoveCallback = (page: number) => void;
type BookPageDialogueMoveCallback = (page: number, dialogue: number) => void;

export default class Book {
    protected _library: Library;
    protected _data: BookData;

    protected _pageMoveCallback: BookPageMoveCallback = () => {};
    protected _pageDialogueMoveCallback: BookPageDialogueMoveCallback = () => {};

    constructor(library: Library, options: BookOptions) {
        this._library = library;
        this._data = {
            ...options,
            id: this._library.books.size,
            key: titleToSnake(options.title),
            description: options.description ?? "",
            cover: (options.cover ?? <div style={{ backgroundColor: "black", color: "white" }}>{options.title}</div>) as React.DetailedReactHTMLElement<{}, HTMLDivElement>,
            readable: !!options.pages?.length,
            pages: options.pages?.map(({ content, conversation }) => ({ content: typeof content === "function" ? content : () => content, conversation: (conversation ?? []).map(({ audio = "", content = "", timeout = 1000 }) => ({ audio: new Audio(audio ?? ""), content, timeout })) })) ?? [
                {
                    content: () => (
                        <div className="d-flex justify-content-between">
                            <Alert className="alert-warning border-warning">
                                <h4 className="fw-bold text-warning-emphasis">LOADING ERROR!</h4>

                                <p className="text-warning-emphasis">
                                    <span className="fw-bold text-warning-emphasis">{this.title}</span> does not contain any pages to be displayed.
                                </p>
                            </Alert>
                        </div>
                    ),
                    conversation: [],
                },
            ],
            activities: { ...options.activities, quiz: options.activities?.quiz ?? new Quiz() },
        };

        this._library.add(this);
    }

    public get key() {
        return this._data.key;
    }

    public get title() {
        return this._data.title;
    }

    public get cover() {
        return this._data.cover;
    }

    public get pages() {
        return this._data.pages;
    }

    public get activities() {
        return this._data.activities;
    }

    public get library() {
        return this._library;
    }

    public saved() {
        return PrivateLibrary.saved(this._data.key);
    }

    public save() {
        PrivateLibrary.save(this._data.key);
    }

    public unsave() {
        PrivateLibrary.unsave(this._data.key);
    }

    public bookmarked() {
        return PrivateLibrary.bookmarked(this._data.key);
    }

    public bookmark(page: number) {
        PrivateLibrary.bookmark(this._data.key, page);
    }

    public unbookmark() {
        PrivateLibrary.unbookmark(this._data.key);
    }

    public setPage(page: number, options: BookPageOptions) {
        if (page < 1) throw new RangeError(`[${this.constructor.name}] "page" cannot be lower than 1!`);

        const { content, conversation } = options;

        // this._data.pages[page - 1] = typeof content === "function" ? content : () => content;
        this._data.pages[page - 1] = { content: typeof content === "function" ? content : () => content, conversation: (conversation ?? []).map(({ audio = "", content = "", timeout = 1000 }) => ({ audio: new Audio(audio), content, timeout })) };
    }

    public get lastPage() {
        return this._data.pages.length;
    }

    public control(options: BookPageDialogueControlOptions) {
        const { page, dialogue: dialogueNumber, type } = options;
        if (type === "previous" || type === "next") return type;

        const data = this._data.pages[page - 1];
        if (!data) return type;

        const dialogue = data.conversation[dialogueNumber];
        if (!dialogue) return type;

        switch (type) {
            case "mute":
            case "unmute": {
                dialogue.audio.updateMuteState();

                break;
            }

            case "repeat": {
                dialogue.audio.repeat();

                break;
            }

            case "play": {
                dialogue.audio.play();

                break;
            }

            case "reset": {
                dialogue.audio.reset();

                break;
            }

            case "pause": {
                dialogue.audio.pause();

                break;
            }
        }

        return type;
    }

    public get Routes() {
        const { activities } = this._data;

        return [
            () => {
                const BookPage = this.render();
                return <Route key={this._data.key} path={`/books/${this._data.key}`} element={<BookPage />} />;
            },
            () => {
                const ActivityPage = this.renderActivities();
                return <Route key={this._data.key} path={`/books/${this._data.key}/activities`} element={<ActivityPage />} />;
            },
            ...Object.keys(activities).map((key) => {
                const activity = activities[key as keyof BookActivitiesData];
                const ActivityTypePage = activity.render();

                return () => <Route key={this._data.key} path={`/books/${this._data.key}/activities/${key}`} element={<ActivityTypePage />} />;
            }),
        ];
    }

    public get entry() {
        return () => {
            const navigate = useNavigate();

            return React.cloneElement(
                this._data.cover,
                {
                    className: `${this._data.cover.props.className ?? ""} user-select-none book-entry rounded-2 justify-content-center d-flex p-3 mb-4 m-2`,
                    onClick: () => navigate(`/books/${this._data.key}/#`),
                },
                this._data.cover.props.children ?? [this._data.title]
            );
        };
    }

    public renderActivities() {
        return () => {
            const [{ activities }, { colorMode }, location, navigate] = [this._data, useColorMode(), useLocation(), useNavigate()];

            // If the user entered the url directly, add the
            // previous pages to the history to allow the back button
            useEffect(() => {
                if (location.key === "default") {
                    navigate(`/`, { replace: true });
                    navigate(`/books/${this._data.key}`);
                    navigate(`/books/${this._data.key}/activities/`);
                }
            }, [navigate, location]);

            return (
                <div data-bs-theme={colorMode}>
                    <InteractiveBookNavigation />

                    <div className="col my-3 mx-3">
                        <span onClick={() => navigate(-1)}>
                            <i className="bi bi-box-arrow-left e-icon"></i>
                        </span>
                    </div>

                    <div className="text-center row-cols-2 d-flex justify-content-between  mx-3 px-3">
                        {Object.keys(activities).map((key, i) => {
                            const activity = activities[key as keyof typeof activities];

                            return (
                                <div key={i} className="col">
                                    <activity.activityButton key={i} />
                                </div>
                            );
                        })}
                    </div>
                </div>
            );
        };
    }

    public render() {
        return () => {
            const navigate = useNavigate();

            const savedData = PrivateLibrary.retrieve()[this._data.key] ?? { savedAt: -1, bookmark: -1 };

            const ref = useRef<HTMLDivElement | null>(null);

            const [[saved, setSaved], [bookmarked, setBookmarked]] = [useState(this.saved()), useState(savedData.bookmark)];
            const [{ colorMode }, [page, setPage], [dialogueNumber, setDialogueNumber], [playState, setPlayState], [autoplay, setAutoplay], [direction, setDirection]] = [useColorMode(), useState(1), useState(0), useState(false), useState(false), useState<"from-left" | "to-left" | "none" | "from-right" | "to-right">("none")];

            const [BookEntry, Page, conversation] = [React.cloneElement(this.entry(), { onClick: void 0 }), this.renderPage(page), this._data.pages[page - 1].conversation];
            const dialogue = conversation[dialogueNumber] as BookPageDialogueData | undefined;

            const [[muted, setMuted]] = [useState(dialogue?.audio.isMuted() ?? false)];

            const colorCounterpart: ColorMode = colorMode === "dark" ? "light" : "dark";
            const { clientWidth, clientHeight } = document.documentElement;
            const basis = Math.min(((clientWidth * 0.85) / 16) * 0.925, ((clientHeight * 0.725) / 9) * 0.925);

            if (dialogue) {
                dialogue.audio.updateMuteState(muted);
                dialogue?.audio.onEnd(() => {
                    setPlayState(false);

                    if (autoplay) moveToDialogue(dialogueNumber + 1);
                });
            }

            const initialCallback = this._pageDialogueMoveCallback;

            this._pageDialogueMoveCallback = (pageNumber, dialogueNumber) => {
                initialCallback(pageNumber, dialogueNumber);

                if (!playState) this.control({ page: pageNumber, dialogue: dialogueNumber, type: "play" });

                setPlayState(true);
            };

            const read = (page: number = 1, dialogue: number = 0) => {
                document.getElementById("book-information")?.classList.add("visually-hidden");
                document.getElementById("book-pages")?.classList.remove("visually-hidden");

                moveToPage(page);
                moveToDialogue(dialogue);
            };

            const moveToPage = (pageNumber: number) => {
                if (pageNumber < 1 || pageNumber > this.lastPage || pageNumber === page) return;

                if (dialogue?.audio) {
                    dialogue.audio.reset();
                    setPlayState(false);
                }

                setDirection(pageNumber < page ? "to-right" : "to-left");
                setTimeout(() => {
                    setPage(pageNumber);

                    this._pageMoveCallback(pageNumber);
                    this._pageDialogueMoveCallback(pageNumber, 0);

                    setDirection(pageNumber < page ? "from-left" : "from-right");
                    setTimeout(() => setDirection("none"), 450);

                    const input = document.getElementById("book-page-input") as HTMLInputElement | null;
                    if (!input) return;

                    input.value = pageNumber.toString();
                }, 450);
            };

            const moveToDialogue = (dialogueNumber: number) => {
                if (dialogueNumber < 0) {
                    setDialogueNumber(0);

                    return moveToPage(page - 1);
                }

                if (dialogueNumber >= conversation.length) {
                    setDialogueNumber(0);

                    return moveToPage(page + 1);
                }

                if (dialogue?.audio) {
                    dialogue.audio.reset();
                    setPlayState(false);
                }

                this._pageDialogueMoveCallback(page, dialogueNumber);
                setDialogueNumber(dialogueNumber);
            };

            useEffect(() => {
                const current = ref.current;
                return () => {
                    if (!current?.classList.contains("visually-hidden")) dialogue?.audio.reset();
                };
            }, [dialogue?.audio]);

            return (
                <div data-bs-theme={colorMode}>
                    <InteractiveBookNavigation />

                    <Container id="book-pages" ref={ref} className="visually-hidden justify-content-center">
                        <div className="user-select-none information my-3 row d-flex">
                            <div className="col">
                                <span
                                    onClick={() => {
                                        document.getElementById("book-information")?.classList.remove("visually-hidden");
                                        document.getElementById("book-pages")?.classList.add("visually-hidden");

                                        dialogue?.audio.reset();
                                        setPlayState(false);
                                    }}
                                >
                                    <i className="bi bi-box-arrow-left e-icon"></i>
                                </span>
                            </div>
                            <div className="col text-center align-content-center fw-bold" style={{ fontSize: "85%" }}>
                                {this.title}
                            </div>
                            <div className="col text-end">
                                {this._data.readable ? (
                                    <span
                                        onClick={() => {
                                            const bookmarkPage = bookmarked === page ? -1 : page;

                                            bookmarkPage > -1 ? this.bookmark(bookmarkPage) : this.unbookmark();
                                            setBookmarked(bookmarkPage);
                                        }}
                                    >
                                        {bookmarked === page ? <i className="bi bi-bookmark-fill e-icon" style={{ fontSize: "225%" }}></i> : <i className="bi bi-bookmark e-icon"></i>}
                                    </span>
                                ) : (
                                    <></>
                                )}
                            </div>
                        </div>

                        {/* minHeight: `72.5vh`, height: `72.5vh`, maxHeight: `72.5vh` */}
                        <Container className={`user-select-none direction-${direction} overflow-hidden d-flex align-items-center justify-content-center`} style={{ minWidth: "85vw", width: "85vw", maxWidth: "85vw", minHeight: "65vh", height: "65vh", maxHeight: "72.5vh" }}>
                            {/* width: "100%", height: document.documentElement.clientWidth < document.documentElement.clientHeight * 0.65 ? `${document.documentElement.clientWidth * 0.65}px` : "72.5vh" */}
                            <div style={{ ...(this._data.readable ? { transform: `scale(${(window.outerHeight * 0.65) / 750})`, transformOrigin: "top left" } : {}), width: `${basis * 16}px`, height: `${basis * 9}px` }}>{Page()}</div>
                        </Container>

                        <Container className="user-select-none d-flex align-items-center justify-content-center gap-3 my-2">
                            {/* Previous Button */}
                            <span
                                onClick={() => {
                                    moveToDialogue(dialogueNumber - 1);
                                }}
                            >
                                <i className={`bi bi-arrow-left btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(254, 237, 0)" }}></i>
                            </span>

                            {/* Mute/Unmute Button */}
                            <span
                                onClick={() => {
                                    this.control({ page, dialogue: dialogueNumber, type: muted ? "unmute" : "mute" });

                                    setMuted(!muted);
                                }}
                            >
                                {muted ? <i className={`bi bi-volume-mute btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(24, 150, 0)" }}></i> : <i className={`bi bi-volume-up btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(48, 238, 0)" }}></i>}
                            </span>

                            {/* Play/Pause Button */}
                            <span
                                onClick={() => {
                                    this.control({ page, dialogue: dialogueNumber, type: playState ? "pause" : "play" });

                                    setPlayState(!playState);
                                }}
                            >
                                {playState ? <i className={`bi bi-pause btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(1, 85, 170)" }}></i> : <i className={`bi bi-play btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(3, 113, 248)" }}></i>}{" "}
                            </span>

                            {/* Auto-Play Button */}
                            <span
                                className={`btn btn-outline-${colorCounterpart}`}
                                style={{
                                    backgroundColor: "rgb(1, 85, 170)",
                                }}
                                onClick={() => {
                                    setAutoplay(!autoplay);
                                }}
                            >
                                {autoplay ? <i className="bi bi-arrow-repeat d-inline-block" style={{ animation: "spin 1.5s linear infinite", animationIterationCount: "infinite" }}></i> : <i className="bi bi-play"></i>}{" "}
                            </span>

                            {/* Repeat Button */}
                            <span
                                onClick={() => {
                                    dialogue?.audio.repeat();

                                    setPlayState(true);
                                }}
                            >
                                <i className={`bi bi-arrow-repeat btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(253, 9, 127)" }}></i>
                            </span>

                            {/* Next Button */}
                            <span
                                onClick={() => {
                                    moveToDialogue(dialogueNumber + 1);
                                }}
                            >
                                <i className={`bi bi-arrow-right btn btn-outline-${colorCounterpart}`} style={{ backgroundColor: "rgb(225, 0, 0)" }}></i>
                            </span>
                        </Container>

                        <div className="d-flex flex-column justify-content-end my-3">
                            <div className="row row-cols-3 d-flex justify-content-between">
                                <div className="col">
                                    {page > 1 ? (
                                        <span
                                            className={`btn btn-outline-${colorCounterpart}`}
                                            onClick={() => {
                                                moveToPage(page - 1);
                                            }}
                                        >
                                            <i className="bi bi-caret-left"></i>
                                        </span>
                                    ) : (
                                        <></>
                                    )}
                                </div>

                                <span className="user-select-none col text-center">
                                    <span className="input-group">
                                        <input
                                            id="book-page-input"
                                            className="form-control"
                                            type="number"
                                            placeholder="Page No."
                                            onChange={(ev) => {
                                                const [{ lastPage }, inputPage] = [this, parseInt(ev.currentTarget.value)];
                                                if (isNaN(inputPage)) return;

                                                const page = inputPage > lastPage ? lastPage : inputPage < 1 ? 1 : inputPage;

                                                ev.currentTarget.value = page.toString();
                                                moveToPage(page);
                                            }}
                                            defaultValue={page.toString()}
                                        />
                                        {/* <span className="user-select-none input-group-text">/</span> */}
                                        <span className={`user-select-none input-group-text`} onClick={() => moveToPage(this.lastPage)}>
                                            : {this.lastPage}
                                        </span>
                                    </span>
                                </span>

                                <div className="col text-end">
                                    {page < this.lastPage ? (
                                        <span
                                            className={`btn btn-outline-${colorCounterpart}`}
                                            onClick={() => {
                                                moveToPage(page + 1);
                                            }}
                                        >
                                            <i className="bi bi-caret-right"></i>
                                        </span>
                                    ) : (
                                        <></>
                                    )}
                                </div>
                            </div>
                        </div>
                    </Container>

                    <div id="book-information" className="mx-1 px-2">
                        <div className="mb-3" onClick={() => (window.history.length > 2 ? navigate(-1) : navigate("/"))}>
                            <i className="bi bi-box-arrow-left e-icon"></i>
                        </div>

                        <div className="d-flex justify-content-center">
                            <div className="d-flex justify-content-center align-content-center" style={{ width: "95%" }}>
                                <div className="row row-cols-2">
                                    <div className="col d-flex justify-content-center align-items-center">{BookEntry}</div>

                                    <div className="col">
                                        <h1 className="fw-bold">{this._data.title}</h1>
                                        <p className="text-wrap text-break" style={{ textAlign: "justify", fontSize: "85%", width: "95%" }}>
                                            {this._data.description}
                                        </p>

                                        <span
                                            className="col-2 mx-2"
                                            onClick={() => {
                                                const state = !saved;

                                                setSaved(state);
                                                state ? this.save() : this.unsave();
                                            }}
                                        >
                                            <OverlayTrigger
                                                placement="auto"
                                                overlay={
                                                    <Popover data-bs-theme={colorMode}>
                                                        <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>
                                                            <span className={`fw-bold badge text-bg-${saved ? "warning" : "success"} mx-1`}>{saved ? "UNSAVE" : "SAVE"}</span>
                                                            <span className="fw-bold">{this._data.title}</span>
                                                        </Popover.Header>

                                                        <Popover.Body>
                                                            <span className="fw-bold badge text-bg-danger">NOTE</span> Saved books are only saved within this browser and device!
                                                        </Popover.Body>
                                                    </Popover>
                                                }
                                            >
                                                <i className="bi bi-heart-fill e-icon" style={{ color: saved ? "rgb(243, 2, 26)" : "rgb(166, 2, 2)" }}></i>
                                                {/* {saved ? <i className="bi bi-heart-fill text-danger e-icon"></i> : <i className="bi bi-heart e-icon"></i>} */}
                                            </OverlayTrigger>
                                        </span>

                                        <span className="col-2 mx-2" onClick={() => read(1)}>
                                            <OverlayTrigger
                                                placement="auto"
                                                overlay={
                                                    <Popover data-bs-theme={colorMode}>
                                                        <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>
                                                            <span className="badge text-bg-info fw-bold mx-1">READ</span>
                                                            <span className="fw-bold">{this.title}</span>
                                                        </Popover.Header>

                                                        <Popover.Body>
                                                            Start reading <span className="fw-bold">{this.title}</span> from the first page.
                                                        </Popover.Body>
                                                    </Popover>
                                                }
                                            >
                                                <i className="bi bi-book e-icon"></i>
                                            </OverlayTrigger>
                                        </span>

                                        {savedData.bookmark > 0 ? (
                                            <span className="col-2 mx-2" onClick={() => read(savedData.bookmark)}>
                                                <OverlayTrigger
                                                    placement="auto"
                                                    overlay={
                                                        <Popover data-bs-theme={colorMode}>
                                                            <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>
                                                                <span className="badge text-bg-info fw-bold mx-1">READ</span>
                                                                <span className="fw-bold">{this.title}</span>
                                                            </Popover.Header>

                                                            <Popover.Body>
                                                                Start reading <span className="fw-bold">{this.title}</span> from the bookmark placed at page {savedData.bookmark}.
                                                            </Popover.Body>
                                                        </Popover>
                                                    }
                                                >
                                                    <i className="bi bi-bookmark-fill e-icon text-info"></i>
                                                </OverlayTrigger>
                                            </span>
                                        ) : (
                                            <></>
                                        )}

                                        <span className="col-2 mx-2" onClick={() => navigate(`/books/${this._data.key}/activities/`)}>
                                            <OverlayTrigger
                                                placement="auto"
                                                overlay={
                                                    <Popover data-bs-theme={colorMode}>
                                                        <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>
                                                            <span className="badge text-bg-primary fw-bold mx-1">PERFORM</span>
                                                            <span className="fw-bold">Activities</span>
                                                        </Popover.Header>

                                                        <Popover.Body>
                                                            Perform activities to test your knowledge about <span className="fw-bold">{this.title}</span>.
                                                        </Popover.Body>
                                                    </Popover>
                                                }
                                            >
                                                <i className="bi bi-pen e-icon"></i>
                                            </OverlayTrigger>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            );
        };
    }

    public renderPage(page: number) {
        return this._data.pages[page - 1].content;
    }
}
