import { OverlayTrigger, Popover } from "react-bootstrap";
import ReactDOM from "react-dom/client";

import Book from "../../components/content/book/Book";

import { MainLibrary } from "../../components/content/library/mainLibrary";

import image from "../../assets/Anino/cover-image.png";
import { useColorMode } from "../../components/interface/ColorModeToggle";

let TEXTBOX_ROOT: ReactDOM.Root, TEXTBOX: HTMLDivElement;

export class Anino extends Book {
    constructor() {
        super(MainLibrary, {
            title: "Anino",
            description: [
                //
                "Sina Maki, isang kambing, at Waldo, isang usa ay magkaibigan.",
                "Habang sila ay tumatanda, nagsimulang makaramdam ng inggit",
                "si Maki sa kanilang pagkakaiba. Nagtungo siya sa isang",
                "paglalakbay upang matutunan ang tunay na halaga ng sarili",
                "at ang kahalagahan ng pagkakaibigan.",
            ].join(" "),

            cover: (
                <div
                    style={{
                        // backgroundColor: "darkseagreen",
                        backgroundImage: `url(${image})`,
                        backgroundSize: "175% 100%",
                        backgroundPosition: "center",
                        backgroundRepeat: "no-repeat",
                    }}
                >
                    <h4 className="align-self-center text-dark fw-bold">Anino</h4>
                </div>
            ) as React.DetailedReactHTMLElement<React.HTMLAttributes<HTMLDivElement>, HTMLDivElement>,
        });

        this._data.activities.quiz
            //
            .create("Ano ang ibigsabihin ng “magkaibigang-pagkit?”", ["Kaaway", "Matalik na kaibigan", "Nag-iibigan", "Wala sa nabanggit"], [1])
            .create('Ano ang ibigsabihin ng “pagkapagal"?', ["Pagkapagod", "Pagkagutom", "Pagkaantok", "Pagkabusog"], [0])
            .create('Sino ang magkaibigan sa istoryang "Anino"?', ["Maki at Waldo", "Waki at Maldo", "Ikaw at ako", "Ang tatay at nanay ni Maki"], [0])
            .create("Sino ang tauhang tinubuan ng malagong sungay?", ["Maki", "Waki", "Waldo", "Maldo"], [2])
            .create("Ano ang naramdaman ni Maki kay Waldo noong nakita niya ang malagong sungay nito?", ["Nainggit", "Nagalit", "Nagutom", "Wala"], [0]);

        this._pageMoveCallback = (pageNumber) => this._pageDialogueMoveCallback(pageNumber, 0);

        this._pageDialogueMoveCallback = (pageNumber, dialogueNumber) => {
            const textbox = document.getElementById("anino-textbox") as HTMLDivElement;

            const conversation = this._data.pages[pageNumber - 1].conversation;
            const dialogue = conversation[dialogueNumber];

            if (TEXTBOX !== textbox) {
                TEXTBOX = textbox;
                TEXTBOX_ROOT = ReactDOM.createRoot(TEXTBOX);
            }

            TEXTBOX_ROOT?.render(dialogue?.content ?? "");
        };
    }

    public static createPage(url: string, child: React.ReactNode) {
        return (
            <div
                className="d-flex flex-column justify-content-end p-2 h-100"
                style={{
                    backgroundImage: `url(${url})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                    backgroundRepeat: "no-repeat",
                }}
            >
                {child}
                {this.craeteTextBox("")}
            </div>
        );
    }

    public static craeteTextBox(content: React.ReactNode) {
        return (
            <div id="anino-textbox" className="text-white border rounded-2 bg-dark bg-opacity-50 p-1" style={{ minHeight: "7.5%", fontSize: "calc(0.35rem + 1vw)" }}>
                {content}
            </div>
        );
    }

    public static createDefinitionPopover(word: string, definition: React.ReactNode) {
        const PopOver = () => {
            const { colorMode } = useColorMode();

            return (
                <OverlayTrigger
                    placement="auto"
                    overlay={
                        <Popover data-bs-theme={colorMode}>
                            <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>{word[0].toUpperCase().concat(word.slice(1).toLowerCase())}</Popover.Header>
                            <Popover.Body>{definition}</Popover.Body>
                        </Popover>
                    }
                >
                    <span className="fw-bold">{word}</span>
                </OverlayTrigger>
            );
        };

        return <PopOver />;
    }
}

export const AninoBook = new Anino();
