/**
 * Redirects the client to the provided URL
 * @param url The URL to redirect the client to
 */
export function redirect(url: string) {
    const anchor = document.createElement("a");

    anchor.href = url;
    anchor.click();

    anchor.remove();
}

/**
 * Updates the string with title case to snake case
 * @param str The string with title case to be converted to snake case
 */
export function titleToSnake(str: string) {
    return str.replace(/\s/g, "_").toLowerCase();
}

export type ColorMode = "dark" | "light";

/**
 * Sets the preferred color mode of the user
 */
export function setPreferredColorMode(mode: ColorMode) {
    localStorage.setItem("color_mode", mode);
}

/**
 * Returns the preferred color mode of the user
 */
export function getPreferredColorMode(): ColorMode {
    const colorMode = localStorage.getItem("color_mode") as ColorMode | undefined;
    if (colorMode) return colorMode;

    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    setPreferredColorMode(mediaQuery.matches ? "dark" : "light");

    return localStorage.getItem("color_mode") as ColorMode;
}
