import { useLocation } from "react-router-dom";
import { Nav, Navbar, NavbarBrand, NavbarCollapse, NavbarToggle, NavItem, NavLink } from "react-bootstrap";

import ColorModeToggle from "./ColorModeToggle";
import { BASENAME } from "../../Main";

interface NavigationItemOptions {
    url?: string;
    content?: string | JSX.Element;
}

interface NavigationProps {
    id: string;
    name?: string | JSX.Element;
    items?: NavigationItemOptions[];
}

export default function Navigation(props: NavigationProps) {
    const location = useLocation();

    const { id, name, items = [] } = props;

    const navbarBrand = (
        <span className="row">
            <div className="col d-flex align-items-center">
                <ColorModeToggle />

                <NavbarBrand id={`navbar-brand-${id}`} className="user-select-none" href={`${BASENAME}/#`}>
                    <span
                        className="fw-bold"
                        onClick={() => {
                            if (document.body.clientWidth > 500 || !document.getElementById(`navbar-content-${id}`)?.classList.contains("show")) return;

                            document.getElementById(`navbar-toggle-${id}`)?.click();
                        }}
                    >
                        {name}
                    </span>
                </NavbarBrand>
            </div>

            <div className="col text-end">
                <NavbarToggle id={`navbar-toggle-${id}`} className="text-end" type="button" data-toggle="collapse" data-target={`#navbar-content-${id}`} aria-controls={`navbar-content-${id}`} aria-expanded="false" aria-label="Toggle Navigation" />
            </div>
        </span>
    );

    if (document.body.clientWidth <= 500) {
        return (
            <Navbar id={`navbar-${id}`} className="mobile-view border-bottom px-3 mb-3" sticky="top" expand="lg">
                {navbarBrand}

                <NavbarCollapse id={`navbar-content-${id}`}>
                    <Nav>
                        {items.map(({ url: defaultUrl, content }) => {
                            const url = `${BASENAME}${defaultUrl}/#`;
                            const current = !!defaultUrl && location.pathname.startsWith(defaultUrl);

                            return (
                                <NavLink key={url} className={`${current ? "fw-bold" : ""}`} href={url} onClick={() => document.getElementById(`navbar-toggle-${id}`)?.click()}>
                                    {content}
                                </NavLink>
                            );
                        })}
                    </Nav>
                </NavbarCollapse>
            </Navbar>
        );
    }

    return (
        <Navbar className="default-view border-bottom justify-content-between border-body px-3 mb-3" sticky="top">
            {navbarBrand}

            <Nav className="nav-underline gap-5 px-2">
                {items.map(({ url: defaultUrl, content }) => {
                    const url = `${BASENAME}${defaultUrl}/#`;
                    const current = !!defaultUrl && location.pathname.startsWith(defaultUrl);

                    return (
                        <NavItem key={url}>
                            <NavLink className="user-select-none" active={current} href={url}>
                                {content}
                            </NavLink>
                        </NavItem>
                    );
                })}
            </Nav>
        </Navbar>
    );
}
