const AUDIO_COLLECTION = new Map<string, Audio>();

type AudioEndCallback = (audio: Audio) => void;

export class Audio {
    protected static _audio: Audio;

    protected _url: string;
    protected _element: HTMLAudioElement;

    constructor(url: string) {
        this._url = url;

        this._element = document.createElement("audio");
        this._element.src = this._url;

        this._element.load();

        AUDIO_COLLECTION.set(this._url, this);
    }

    public static resetAllAudio() {
        AUDIO_COLLECTION.forEach((audio) => audio.reset());
    }

    public get element() {
        return this._element;
    }

    public async play() {
        try {
            if (Audio._audio && Audio._audio !== this) Audio._audio.reset();

            Audio._audio = this;

            await this._element.play();
        } catch (err: any) {
            //  console.warn(`Audio Error: ${err}`);
        }
    }

    public pause() {
        this._element.pause();
    }

    public reset() {
        this.pause();
        this._element.currentTime = 0;
    }

    public repeat() {
        this.reset();
        this.play();
    }

    public updateMuteState(mute: boolean = !this._element.muted) {
        this._element.muted = mute;
    }

    public isMuted() {
        return this._element.muted;
    }

    public onEnd(callback: AudioEndCallback) {
        this._element.onended = () => callback(this);
    }
}
