import { useColorMode } from "../components/interface/ColorModeToggle";
import InteractiveBookNavigation from "../components/interface/navigationBar";

export default function AboutUs() {
    const { colorMode } = useColorMode();

    return (
        <div data-bs-theme={colorMode}>
            <InteractiveBookNavigation />

            <div className="min-vh-25 fw-bold d-flex justify-content-center align-content-center mt-5" style={{ height: "12.5vh" }}>
                <h1>IV Of 1-2</h1>
            </div>

            <div className="mx-3 px-2">
                We are <span className="fw-bold">IV of 1-2</span>, a research group from BSIT 1-2 (A.Y 24-25), the developers of this simple interactive learning system that attempts to help students learn in another integrated way.
            </div>
        </div>
    );
}
