import { Anino, AninoBook } from "../Book";

import scene1 from "../../../assets/Anino/pages/1/scene-1.gif";
import narrator001 from "../../../assets/Anino/pages/1/audios/1Narrator001.mp3";

AninoBook.setPage(
    // Page Number
    1,

    // Page Options
    {
        content: () => {
            return Anino.createPage(scene1, <div></div>);
        },
        conversation: [
            // Narrator
            {
                audio: narrator001,
                content: (
                    <span>
                        Narrator: Sa isang malawak na bukirin,{" "}
                        {Anino.createDefinitionPopover(
                            "magkaibigang-pagkit",
                            <span>
                                <i>Best friends</i>, tunay na magkaibigan, matalik na magkaibigan.
                            </span>
                        )}{" "}
                        sina Maki at Waldo. Halos lahat ng oras magkasama sila. Noong sila ay bata pa, madalas silang mapagkamalang magkapatid.
                    </span>
                ),
                timeout: 1000,
            },
        ],
    }
);
