import { HashRouter, Route, Routes } from "react-router-dom";

import Home from "./pages/Home";
import AboutUs from "./pages/AboutUs";
import Contacts from "./pages/Contacts";
import Collection from "./pages/Collection";

import "./collections/collection";
import { LIBRARY_COLLECTIONS } from "./components/content/library/Library";

export const BASENAME = "/InteractiveBook/#";

export default function Main() {
    return (
        <HashRouter>
            <Routes>
                {LIBRARY_COLLECTIONS.flatMap((library) => [...library.books.values()].flatMap((book, i) => book.Routes.flatMap((route) => route())))}

                <Route path="/" element={<Home />} />
                <Route path="/about-us" element={<AboutUs />} />
                <Route path="/contacts" element={<Contacts />} />
                <Route path="/collection" element={<Collection />} />
            </Routes>
        </HashRouter>
    );
}
