import { useState } from "react";

import { ColorMode } from "../../../../utils";
import { useColorMode } from "../../../interface/ColorModeToggle";

import { QuizOptions } from "./Quiz";

interface QuizProps extends QuizOptions {
    itemNumber?: number;
    result: { value: string };
}

export default function QuizEntry(props: QuizProps) {
    const { itemNumber, question, choices = [], result } = props;

    const [{ colorMode }, [choice, setChoice]] = [useColorMode(), useState(result.value)];
    const colorCounterpart: ColorMode = colorMode === "dark" ? "light" : "dark";

    const updateChoice = (choice: string) => {
        setChoice(choice);
        props.result.value = choice;
    };

    return (
        <div>
            <h2 className="text-center text-wrap text-break mx-3 pb-4">
                {itemNumber ? <span className="badge rounded-5 border fw-bold">{itemNumber}</span> : ""} {question}
            </h2>

            {choices.length ? (
                <div className="row-cols-2 d-flex flex-wrap justify-content-between">
                    {choices.map((_choice, i) => {
                        return (
                            <div key={i} className="col">
                                <div className={`${choice === _choice ? "text-success" : ""} d-flex justify-content-center align-items-center border${choice === _choice ? `-5` : ``} ${choice === _choice ? "border-success" : ""} rounded-3 btn btn-outline-${colorCounterpart} fs-5 fw-bold`} style={{ minHeight: "7.5vh" }} onClick={() => updateChoice(_choice)}>
                                    {_choice}
                                </div>
                            </div>
                        );
                    })}
                </div>
            ) : (
                <></>
            )}
        </div>
    );
}
