import React, { createContext, ReactNode, useContext, useEffect, useState } from "react";

import { ColorMode, getPreferredColorMode, setPreferredColorMode } from "../../utils";

export interface ColorModeContextValue {
    colorMode: ColorMode;
    setColorMode: typeof setPreferredColorMode;
}

export const ColorModeContext = createContext<ColorModeContextValue>({ colorMode: getPreferredColorMode(), setColorMode: () => {} });

export const ColorModeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [colorMode, setColorMode] = useState(getPreferredColorMode());

    useEffect(() => {
        document.body.className = `${colorMode}-theme`;
    }, [colorMode]);

    return (
        <ColorModeContext.Provider
            value={{
                colorMode,
                setColorMode: (mode) => {
                    setColorMode(mode);
                    setPreferredColorMode(mode);
                },
            }}
        >
            {children}
        </ColorModeContext.Provider>
    );
};

export const useColorMode = () => {
    const context = useContext(ColorModeContext);
    if (!context) throw new Error(`[]`);

    return context;
};

export default function ColorModeToggle() {
    const { colorMode, setColorMode } = useColorMode();
    const colorCounterpart: ColorMode = colorMode === "dark" ? "light" : "dark";

    return (
        <span className="color-mode-toggle" onClick={() => setColorMode(colorCounterpart)}>
            {colorMode === "dark" ? <i className="bi bi-book-half mx-2 e-icon"></i> : <i className="bi bi-book-fill mx-2 e-icon"></i>}
        </span>
    );
}
