import DefaultContactInformation from "../components/content/contact/contactInfo";
import InteractiveBookNavigation from "../components/interface/navigationBar";

import { useColorMode } from "../components/interface/ColorModeToggle";

export default function Contacts() {
    const { colorMode } = useColorMode();

    return (
        <div data-bs-theme={colorMode}>
            <InteractiveBookNavigation />

            <DefaultContactInformation />
        </div>
    );
}
