import { useState } from "react";
import { Container, OverlayTrigger, Popover } from "react-bootstrap";

import Book from "../book/Book";
import { useColorMode } from "../../interface/ColorModeToggle";
import { ColorMode } from "../../../utils";

type LibraryAccessibility = "Public" | "Private";

interface LibraryData extends Required<LibraryOptions> {}
interface LibraryOptions {
    accessibility?: LibraryAccessibility;
}

export const LIBRARY_COLLECTIONS: Library[] = [];

export class Library {
    protected _data: LibraryData;
    protected _books: Map<string, Book> = new Map();

    constructor(options: LibraryOptions) {
        this._data = { ...options, accessibility: options.accessibility ?? "Public" };

        if (this._data.accessibility === "Public") LIBRARY_COLLECTIONS.push(this);
    }

    public get books() {
        return this._books;
    }

    public add(book: Book) {
        if (!this._books.has(book.key)) this._books.set(book.key, book);
    }

    public get(key: string) {
        return this._books.get(key);
    }

    /**
     * @NOTE Only works for exact searches
     */
    public find(query?: string): Book[] {
        const books = [...this._books.values()];
        if (!query) return books;

        return books.filter((book) => book.title.replace(/\s+/g, " ").toLowerCase().includes(query.toLowerCase()));
    }

    public get Component() {
        const library: Library = this;

        return function LibraryComponent() {
            const [[query, setQuery], { colorMode }] = [useState(""), useColorMode()];
            const books = library.find(query);

            const colorCounterpart: ColorMode = colorMode === "dark" ? "light" : "dark";

            return (
                <div>
                    {library.books.size >= 20 ? (
                        <div className="search-container input-group flex-nowrap px-3 mb-3">
                            <span id="search-icon" className={`input-group-text text-${colorCounterpart} btn btn-outline-${colorCounterpart}`} onClick={() => document.getElementById("search-input")?.focus()}>
                                <i className="bi bi-search"></i>
                            </span>

                            <input id="search-input" className={`user-select-none form-control border-${colorCounterpart}`} type="seach" placeholder="Search" onChange={(ev) => setQuery(ev.currentTarget.value)} />
                        </div>
                    ) : (
                        <div></div>
                    )}

                    <Container id="book-section" className="user-select-none d-flex flex-wrap align-content-around">
                        {library.books.size ? (
                            books.length ? (
                                books.map((book, i) => {
                                    return (
                                        <OverlayTrigger
                                            key={i}
                                            placement="auto"
                                            delay={{ hide: 0.25, show: 0.15 }}
                                            overlay={
                                                <Popover data-bs-theme={colorMode}>
                                                    <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>{book.title}</Popover.Header>
                                                    <Popover.Body>
                                                        Click to read <span className="fw-bold">{book.title}</span>
                                                    </Popover.Body>
                                                </Popover>
                                            }
                                        >
                                            <div className="position-relative">
                                                {book.saved() ? <i className="bi bi-heart e-icon text-danger position-absolute bottom-0 end-0 px-3 py-4" style={{ pointerEvents: "none" }}></i> : <></>}
                                                {book.bookmarked() ? <i className="bi bi-bookmark-fill e-icon text-info position-absolute top-0 end-0 px-2" style={{ pointerEvents: "none" }}></i> : <></>}

                                                {<book.entry />}
                                            </div>
                                        </OverlayTrigger>
                                    );
                                })
                            ) : (
                                <h6 className="text-wrap text-break text-center px-3" style={{ width: "85%" }}>
                                    No books for the query "<span className="fw-bold">{query}</span>" were found.
                                </h6>
                            )
                        ) : (
                            <h6 className="text-wrap text-break text-center px-3">No books are currently stored in this library!</h6>
                        )}
                    </Container>
                </div>
            );
        };
    }
}
