import narrator010 from "../../../assets/Anino/pages/10/audios/10Narrator009.mp3";
import maki012 from "../../../assets/Anino/pages/10/audios/10Maki012.mp3";

AninoBook.setPage(
    // Page Number
    10,

    // Page Options
    {
        content: () => Anino.createPage(scene10, <div></div>),

        conversation: [
            // Narrator
            {
                audio: narrator010,
                content: "Narrator: Natutunan ni Maki na ang bawat nilalang ay may natatanging ganda at kahulugan. Ang paghahanap ng sariling halaga ay hindi nangangailangan ng pagkakapareho sa iba.",
                timeout: 1000,
            },
            {
                audio: maki012,
                content: "Maki: Ngayon, tanggap ko na ang aking sarili. At sa wakas, natagpuan ko ang kapayapaan.",
                timeout: 1000,
            },
        ],
    }
);
