import { OverlayTrigger, Popover } from "react-bootstrap";

import "./ContactInformation.css";

import { redirect } from "../../../utils";
import { useColorMode } from "../../interface/ColorModeToggle";

interface ContactInformationProps {
    email: string;
    phoneNumber?: string;
}

export default function ContactInformation(props: ContactInformationProps) {
    const [{ email }, { colorMode }] = [props, useColorMode()];

    return (
        <div className="mx-3 py-2">
            <h1 className="text-center fw-bold">Contact Us</h1>

            <p className="text-center">Notify us about any concerns or thoughts regarding this project!</p>

            <OverlayTrigger
                placement="auto"
                delay={{ hide: 0.25, show: 0.1 }}
                overlay={
                    <Popover data-bs-theme={colorMode}>
                        <Popover.Header style={{ color: `var(--${colorMode}-theme-color)` }}>
                            Email <span className="text-info">{email}</span>
                        </Popover.Header>

                        <Popover.Body>
                            Press/click to compose an email to be sent to <span className="text-info">{email}</span>
                        </Popover.Body>
                    </Popover>
                }
            >
                <div className="text-center" onClick={() => redirect(`mailto:${email}?subject=Project Concerns/Thoughts&body=''"`)}>
                    <i className="bi bi-envelope e-icon"></i>
                </div>
            </OverlayTrigger>
        </div>
    );
}
