import { Library } from "./Library";
import { MainLibrary } from "./mainLibrary";

import "../../../collections/collection";

interface BookData {
    savedAt: number;
    bookmark: number;
}

class PrivateLibraryClass extends Library {
    constructor() {
        super({ accessibility: "Private" });
    }

    protected load() {
        const saved = this.retrieve();

        for (const key in saved) {
            const book = MainLibrary.get(key);
            if (!book) {
                delete saved[key];

                continue;
            }

            this._books.set(key, book);
        }

        localStorage.setItem("books", JSON.stringify(saved));
    }

    public update(key: string, data: Partial<BookData>) {
        const saved = this.retrieve();
        const bookData = saved[key] ?? { savedAt: -1, bookmark: -1 };

        for (const k in data) {
            const key = k as keyof BookData;
            bookData[key] = data[key] ?? bookData[key];
        }

        saved[key] = bookData;
        localStorage.setItem("books", JSON.stringify(saved));

        this.clean(key);
    }

    public retrieve() {
        return JSON.parse(localStorage.getItem("books") ?? `{}`) as Record<string, BookData>;
    }

    public fetch(key: string): BookData | undefined {
        return this.retrieve()[key];
    }

    public save(key: string) {
        if (this.saved(key)) return;

        const book = MainLibrary.get(key);
        if (!book) return;

        this.update(key, { savedAt: Date.now() });
        if (!this._books.has(key)) this._books.set(key, book);
    }

    public bookmark(key: string, page: number) {
        const book = MainLibrary.get(key);
        if (!book) return;

        this.update(key, { bookmark: page });
        this._books.set(key, book);
    }

    public unsave(key: string) {
        this.update(key, { savedAt: -1 });
    }

    public unbookmark(key: string) {
        this.update(key, { bookmark: -1 });
    }

    public saved(key: string) {
        return (this.fetch(key)?.savedAt ?? -1) > -1;
    }

    public bookmarked(key: string) {
        return (this.fetch(key)?.bookmark ?? -1) > -1;
    }

    public clean(key: string) {
        const saved = this.retrieve();
        const data = saved[key] ?? { savedAt: -1, bookmark: -1 };

        if (data.savedAt === -1 && data.bookmark === -1) {
            delete saved[key];
            localStorage.setItem("books", JSON.stringify(saved));

            return this._books.delete(key);
        } else return false;
    }

    public get Component(): () => JSX.Element {
        this.load();

        return super.Component;
    }
}

export const PrivateLibrary = new PrivateLibraryClass();
export const PrivateLibraryComponent = PrivateLibrary.Component;
