import { Anino, AninoBook } from "../Book";

import scene4 from "../../../assets/Anino/pages/4/scene-4.gif";
import mother001 from "../../../assets/Anino/pages/4/audios/4Mother001.mp3";
import father001 from "../../../assets/Anino/pages/4/audios/4Father001.mp3";
import maki004 from "../../../assets/Anino/pages/4/audios/4Maki004.mp3";

AninoBook.setPage(
    // Page Number
    4,

    // Page Options
    {
        content: () => Anino.createPage(scene4, <div></div>),
        conversation: [
            {
                audio: mother001,
                content: "Ina: Anak, tayong mga kambing ay maikli ang sungay. May balbas tayo, at hindi gaanong tumatangkad. Iba ang anyo natin kaysa sa mga usa. Kahit di tayo tulad nila masaya kami sa ating anyo.",
                timeout: 1000,
            },
            {
                audio: father001,
                content: "Ama: Tama anak. Wag mong piliting baguhin ang iyong kalikasan. Ang bawat nilalang ay may kahalagahan.",
                timeout: 1000,
            },
            {
                audio: maki004,
                content: "Maki: Hindi ko kailangan ng mga payo ninyo. Hahanap ako ng paraan upang maging espesyal, katulad ni Waldo. Pagbalik ko'y makikita ninyo, sanga-sanga na rin ang sungay ko.",
                timeout: 1000,
            },
        ],
    }
);
