import { useEffect, useState } from "react";
import ReactDOM from "react-dom/client";
import { useLocation, useNavigate } from "react-router-dom";

import config from "../../../../config.json";

import { Activity, ActivityData } from "../Abstract";
import QuizEntry from "./QuizEntry";

import { useColorMode } from "../../../interface/ColorModeToggle";
import InteractiveBookNavigation from "../../../interface/navigationBar";
import { ColorMode } from "../../../../utils";

interface QuizData extends Required<QuizOptions> {}

export interface QuizOptions extends ActivityData {
    question: string;
    choices: string[];
    accepted: number[];
}

interface GeneratedQuizData {
    quiz: QuizOptions;
    element: JSX.Element;
    result: { value: string };
}

interface SubmissionData {
    score: number;
    items: JSX.Element[];
}

export class Quiz extends Activity {
    protected entries: QuizData[] = [];
    protected generated: GeneratedQuizData[] = [];

    public render(): React.FC {
        this.start();

        return () => {
            const [{ colorMode }, location, navigate] = [useColorMode(), useLocation(), useNavigate()];
            const [item, setItem] = useState(1);

            const colorCounterpart: ColorMode = colorMode === "dark" ? "light" : "dark";

            // If the user entered the url directly, add the
            // previous pages to the history to allow the back button
            useEffect(() => {
                if (location.key === "default") {
                    const data = { accumulation: "" };

                    for (const part of location.pathname.split("/")) {
                        data.accumulation += `${data.accumulation.endsWith("/") ? "" : "/"}${part}`;

                        if (part !== "books") navigate(data.accumulation, { replace: part === "" });
                    }
                }
            }, [navigate, location]);

            const data = this.generated[item - 1] ?? <></>;

            return (
                <div data-bs-theme={colorMode}>
                    <InteractiveBookNavigation />

                    <div className="col my-3 mx-3">
                        <span onClick={() => navigate(-1)}>
                            <i className="bi bi-box-arrow-left e-icon"></i>
                        </span>
                    </div>

                    <div id="content-container" className="mx-3 mt-5" style={{ minHeight: "72.5vh", maxHeight: "72.5vh" }}>
                        {data.element}
                    </div>

                    <div className="row-cols-2 d-flex justify-content-between mx-3">
                        {/* Previous Button */}
                        <div className="col">
                            {item > 1 && item <= this.generated.length ? (
                                <span className={`btn btn-outline-${colorCounterpart}`} onClick={() => setItem(item - 1)}>
                                    <i className="bi bi-caret-left"></i>
                                </span>
                            ) : (
                                <></>
                            )}
                        </div>

                        <div className="col text-end">
                            {item < this.generated.length ? (
                                <span className={`btn btn-outline-${colorCounterpart}`} onClick={() => setItem(item + 1)}>
                                    <i className="bi bi-caret-right"></i>
                                </span>
                            ) : item === this.generated.length ? (
                                <span
                                    className={`btn btn-outline-${colorCounterpart}`}
                                    onClick={() => {
                                        const data = this.submit();

                                        const container = document.getElementById("content-container") as HTMLDivElement | null;
                                        if (!container) return;

                                        // To move to the next item and remove
                                        // the previous arrow and submit button
                                        setItem(item + 1);

                                        const root = ReactDOM.createRoot(container);

                                        const percentage = (data.score / data.items.length) * 100;
                                        const color = percentage >= 50 ? (percentage >= 75 ? "text-success" : "text-info") : "text-secondary";

                                        const submit = () => {
                                            root.render(
                                                <div className="direction-from-top">
                                                    <h2 className="text-center" style={{ transition: "all 0.2s", transform: "translateX(0)" }}>
                                                        Your quiz has been submitted and is being analyzed
                                                    </h2>

                                                    <div className="d-flex justify-content-center">
                                                        <i className="bi bi-arrow-repeat e-icon" style={{ animation: "spin 1.5s linear infinite" }}></i>
                                                    </div>
                                                </div>
                                            );

                                            setTimeout(() => {
                                                root.render(
                                                    <div className="direction-from-bottom" style={{ transition: "all 0.5s" }}>
                                                        <h2 className="text-center fw-bold my-4">
                                                            QUIZ RESULT (
                                                            <span className={color}>
                                                                {data.score}/{data.items.length}
                                                            </span>
                                                            )<div className={`text-center ${color} fw-bold fs-5 mt-4`}>{percentage >= 50 ? (percentage >= 75 ? "Excellent job! Keep aiming high and challenging yourself!" : "Good work! We know you can achieve even more next time!") : "You did your best, and that's what matters! It's a great opportunity to learn and grow!"}</div>
                                                        </h2>

                                                        {data.items}
                                                    </div>
                                                );
                                            }, 2500);
                                        };

                                        submit();
                                    }}
                                >
                                    <span>Submit</span>
                                </span>
                            ) : (
                                <></>
                            )}
                        </div>
                    </div>
                </div>
            );
        };
    }

    public submit() {
        const data: SubmissionData = { score: 0, items: [] as JSX.Element[] };

        this.generated.forEach(({ quiz, result }, i) => {
            const correct = quiz.accepted.some((i) => quiz.choices[i] === result.value);

            data.score += Number(correct);
            data.items.push(
                <div key={i} className="justify-content-between my-3">
                    <span className="me-2">{correct ? <i className="bi bi-check-lg text-success-emphasis fw-bold"></i> : <i className="bi bi-x-lg text-danger fw-bold"></i>}</span> <span className={`badge rounded-5 border fw-bold`}>{i + 1}</span> <span className={`text-${correct ? "success" : "danger"}`}>{quiz.question}</span>
                    <div className="mx-5">{result.value || "N/A"}</div>
                </div>
            );
        });

        return data;
    }

    public create(question: string, choices: string[], accepted: number[] = [-1]) {
        if (!choices.length) throw new RangeError(`[${this.constructor.name}] "choices" must have at least one element to give users choices to choose from!`);

        this.entries.push({ question, choices, accepted });

        return this;
    }

    public start(count: number = config.activities.quiz.items_per_book, displayItem: boolean = true) {
        const indices = new Map<number, void>();
        const quizCount = Math.min(this.entries.length, count);

        this.generated = [];

        while (indices.size < quizCount) {
            const itemNumber = indices.size + 1;

            const random = Math.floor(Math.random() * this.entries.length);
            if (indices.has(random)) continue;

            const quiz = this.entries[random];
            const data: GeneratedQuizData = { quiz, element: <></>, result: { value: "" } };

            data.element = <QuizEntry key={itemNumber} itemNumber={displayItem ? itemNumber : void 0} {...quiz} result={data.result} />;
            this.generated.push(data);

            indices.set(random);
        }

        return this.generated;
    }

    public get activityButton() {
        return () => {
            const navigate = useNavigate();

            return (
                <div
                    className="fw-bold fs-2 align-content-center rounded rounded-3 btn btn-outline-info"
                    style={{ height: "10vh", width: "75%" }}
                    onClick={() => {
                        this.start();
                        navigate("quiz");
                    }}
                >
                    Quiz
                </div>
            );
        };
    }
}
