import { Anino, AninoBook } from "../Book";

import scene6 from "../../../assets/Anino/pages/6/scene-6.gif";
import narator005 from "../../../assets/Anino/pages/6/audios/6Narrator005.mp3";
import maki006 from "../../../assets/Anino/pages/6/audios/6Maki006.mp3";

AninoBook.setPage(
    // Page Number
    6,

    // Page Options
    {
        content: () => Anino.createPage(scene6, <div></div>),

        conversation: [
            // Narrator
            {
                audio: narator005,
                content: <span>Narrator: Sa tindi ng {Anino.createDefinitionPopover("pagkapagal", "pagod, kapaguran.")} at gutom ni Maki, ang hangaring malaon nang pinapangarap pa rin ang nananaig sa isip.</span>,
                timeout: 1000,
            },
            {
                audio: maki006,
                content: "Maki: Wala na akong lakas… Hindi…. ko kayang…. magpatuloy.",
                timeout: 1000,
            },
        ],
    }
);
