import { Anino, AninoBook } from "../Book";

import scene2 from "../../../assets/Anino/pages/2/scene-2.gif";
import maki001 from "../../../assets/Anino/pages/2/audios/2Maki001.mp3";
import waldo001 from "../../../assets/Anino/pages/2/audios/2Waldo001.mp3";
import maki002 from "../../../assets/Anino/pages/2/audios/2Maki002.mp3";
import narrator002 from "../../../assets/Anino/pages/2/audios/2Narrator002.mp3";

AninoBook.setPage(
    // Page Number
    2,

    // Page Options
    {
        content: () => Anino.createPage(scene2, <div></div>),
        conversation: [
            {
                audio: maki001,
                content: "Maki: Waldo, bakit habang humahaba ang sungay mo nagkakaroon ito ng sanga?",
                timeout: 1000,
            },
            {
                audio: waldo001,
                content: "Waldo: Ganyan ang usa. Parang puno ang aming sungay, na lumalaki at dumadami.",
                timeout: 1000,
            },
            {
                audio: maki002,
                content: "Maki: Ahh ga'non ba ang galing naman ng mga usa… Kahit mag sangay ka, kaibigan parin kita!",
                timeout: 1000,
            },
            {
                audio: narrator002,
                content: "Narrator: Habang tumatagal, unti-unting nagkakaroon ng inggit sa puso ni Maki.",
                timeout: 1000,
            },
        ],
    }
);
